def maxPivotsAfterChange(nums, k):
    n = len(nums)
    pre = [0]
    for x in nums:
        pre.append(pre[-1] + x)
    total = pre[n]
    diff = [0] * n
    right = {}
    for q in range(1, n):
        diff[q] = 2 * pre[q] - total
        right[diff[q]] = right.get(diff[q], 0) + 1
    left = {}
    best = right.get(0, 0)
    for i in range(n):
        if 1 <= i <= n - 1:
            d = diff[i]
            right[d] -= 1
            left[d] = left.get(d, 0) + 1
        delta = k - nums[i]
        best = max(best, right.get(-delta, 0) + left.get(delta, 0))
    return best
